exercises.solution:
def dernier_saut(sauts):
    for numero, ip, ms in reversed(sauts):
        if ip is not None:
            return ip
    return None

def plus_grand_bond(sauts):
    meilleur = [0, 0]
    precedent = None
    for numero, ip, ms in sauts:
        if ms is None:
            continue
        if precedent is not None and ms - precedent > meilleur[1]:
            meilleur = [numero, ms - precedent]
        precedent = ms
    return meilleur

