exercises.solution:
import ipaddress

def premier_public(sauts):
    for numero, ip, ms in sauts:
        if ip is not None and not ipaddress.ip_address(ip).is_private:
            return numero
    return None

def diagnostic(sauts, destination):
    for numero, ip, ms in sauts:
        if ip == destination:
            return "atteinte en " + str(numero) + " sauts"
    for numero, ip, ms in reversed(sauts):
        if ip is not None:
            return "bloqué après le saut " + str(numero) + " (" + ip + ")"
    return "aucune réponse"
